export type RuntimeOrbitPrimitive = (typeof RUNTIME_ORBIT_PRIMITIVES)[number]
export type RuntimeOrbitPrimitiveKey = RuntimeOrbitPrimitive['key']
export type RuntimeOrbitOperationName = RuntimeOrbitPrimitive['operation']
export type RuntimeOrbitPrimitiveFamily = RuntimeOrbitPrimitive['family']

export const RUNTIME_ORBIT_PRIMITIVE_KEYS = RUNTIME_ORBIT_PRIMITIVES.map(
  (primitive) => primitive.key
) as readonly RuntimeOrbitPrimitiveKey[]

export const RUNTIME_ORBIT_OPERATION_NAMES = RUNTIME_ORBIT_PRIMITIVES.map(
  (primitive) => primitive.operation
) as readonly RuntimeOrbitOperationName[]

export interface RuntimeOrbitUsageEntry {
  readonly operation: RuntimeOrbitOperationName
  readonly key?: string | undefined
  readonly model?: string | undefined
  readonly sizeBytes?: number | undefined
  readonly durationMs: number
  readonly error?: string | undefined
}

export interface RuntimeOrbitUsageSink {
  readonly record: (entry: RuntimeOrbitUsageEntry) => void
}

export type RuntimeOrbitCallable = (args: unknown) => Promise<unknown>
export type RuntimeOrbitUsageMeta = Partial<
  Omit<RuntimeOrbitUsageEntry, 'operation' | 'durationMs' | 'error'>
>
export type RuntimeOrbitMetaExtractor = (args: unknown, result: unknown) => RuntimeOrbitUsageMeta

export interface RuntimeOrbitPrepareInput {
  readonly key?: string | undefined
  readonly metadata?: RuntimeMetadata | undefined
}

export interface RuntimeOrbitPreparedProvider extends PreparedRuntimeProvider {
  readonly kind: 'orbit'
  readonly key: string
  readonly metadata?: RuntimeMetadata | undefined
}

export interface RuntimeOrbitProvider {
  readonly prepare: (
    input?: RuntimeOrbitPrepareInput | undefined
  ) => Effect.Effect<RuntimeOrbitPreparedProvider, RuntimeError>
}

export const RuntimeOrbitProvider = Context.Service<RuntimeOrbitProvider>(
  '@hrbr/runtime-provider-orbit/RuntimeOrbitProvider'
)

export function runtimeOrbitDispatchKey(key: RuntimeOrbitPrimitiveKey): string {
  return RUNTIME_ORBIT_DISPATCH_PREFIX + key
}

const FORBIDDEN_KEY_SEGMENTS = /(?:^|\/)\.\.(?:\/|$)/

export function validateRuntimeOrbitUserKey(key: string): void {
  if (!key || key.length === 0) throw new Error('orbit: key must be non-empty')
  if (key.length > 512) throw new Error('orbit: key must be ≤512 chars')
  if (FORBIDDEN_KEY_SEGMENTS.test(key)) throw new Error("orbit: key must not contain '..'")
  if (key.startsWith('/') || key.startsWith('\\')) {
    throw new Error('orbit: key must not start with / or \\')
  }
}

export function scopeRuntimeOrbitCacheKey(workspaceId: string, userKey: string): string {
  validateRuntimeOrbitUserKey(userKey)
  return RUNTIME_ORBIT_CACHE_KEY_PREFIX + workspaceId + ':' + userKey
}

function safeMeta(
  extractMeta: RuntimeOrbitMetaExtractor | undefined,
  args: unknown,
  result: unknown
): RuntimeOrbitUsageMeta {
  if (!extractMeta) return {}
  try {
    return extractMeta(args, result)
  } catch {
    return {}
  }
}

function recordUsage(sink: RuntimeOrbitUsageSink | undefined, entry: RuntimeOrbitUsageEntry): void {
  if (!sink) return
  try {
    sink.record(entry)
  } catch {
    // Usage recording must not change user code behavior.
  }
}

export function traceRuntimeOrbitOperation(
  sink: RuntimeOrbitUsageSink | undefined,
  operation: RuntimeOrbitOperationName,
  fn: RuntimeOrbitCallable,
  extractMeta?: RuntimeOrbitMetaExtractor | undefined
): RuntimeOrbitCallable {
  return async (args: unknown): Promise<unknown> => {
    const startedAt = Date.now()
    try {
      const result = await fn(args)
      recordUsage(sink, {
        operation,
        ...safeMeta(extractMeta, args, result),
        durationMs: Date.now() - startedAt,
      })
      return result
    } catch (err) {
      recordUsage(sink, {
        operation,
        ...safeMeta(extractMeta, args, undefined),
        durationMs: Date.now() - startedAt,
        error: err instanceof Error ? err.message : String(err),
      })
      throw err
    }
  }
}

export interface RuntimeOrbitSurfaceSourceOptions {
  readonly workspaceVariableName?: string | undefined
  readonly orbitVariableName?: string | undefined
  readonly hrbrVariableName?: string | undefined
  readonly exposeOrbit?: boolean | undefined
  readonly exposeHrbr?: boolean | undefined
  readonly exposeGlobalHrbr?: boolean | undefined
  readonly jobsExpression?: string | undefined
  readonly dbExpression?: string | undefined
  readonly callExpression?:
    | ((key: RuntimeOrbitPrimitiveKey, argsExpression: string) => string)
    | undefined
}

function defaultRuntimeOrbitCall(key: RuntimeOrbitPrimitiveKey, argsExpression: string): string {
  return '__call(' + JSON.stringify(runtimeOrbitDispatchKey(key)) + ', ' + argsExpression + ')'
}

function runtimeOrbitCall(
  options: RuntimeOrbitSurfaceSourceOptions,
  key: RuntimeOrbitPrimitiveKey,
  argsExpression: string
): string {
  return (options.callExpression ?? defaultRuntimeOrbitCall)(key, argsExpression)
}

function defaultRuntimeOrbitJobsExpression(): string {
  return 'typeof jobs === "undefined" ? new Proxy({}, { get: (_, name) => async () => { throw new Error("ORBIT_JOB_NOT_DEPLOYED: no WFP deployment for job \'" + String(name) + "\' in this workspace"); } }) : jobs'
}

export function createRuntimeOrbitSurfaceSource(
  options: RuntimeOrbitSurfaceSourceOptions = {}
): string {
  const workspace = options.workspaceVariableName ?? '__hrbr_workspace'
  const orbit = options.orbitVariableName ?? 'orbit'
  const hrbr = options.hrbrVariableName ?? 'hrbr'
  const exposeOrbit = options.exposeOrbit ?? true
  const exposeGlobalHrbr = options.exposeGlobalHrbr ?? true
  const dbExpression =
    options.dbExpression ??
    [
      '{',
      '    exec: (sql, params) => ' + runtimeOrbitCall(options, 'db_exec', '{ sql, params }') + ',',
      '    query: (sql, params) => ' +
        runtimeOrbitCall(options, 'db_query', '{ sql, params }') +
        ',',
      '    first: (sql, params) => ' +
        runtimeOrbitCall(options, 'db_first', '{ sql, params }') +
        ',',
      '    batch: (statements) => ' + runtimeOrbitCall(options, 'db_batch', '{ statements }') + ',',
      '  }',
    ].join('\n')
  const lines = [
    'function __hrbr_tools_search_args(query, opts) {',
    '  if (query && typeof query === "object" && !Array.isArray(query)) return { ...query, ...(opts ?? {}) };',
    '  return { query, ...(opts ?? {}) };',
    '}',
    'const ' + workspace + ' = {',
    '  storage: {',
    '    put: (key, data, opts) => ' +
      runtimeOrbitCall(options, 'storage_put', '{ key, data, ...opts }') +
      ',',
    '    get: (key, opts) => ' + runtimeOrbitCall(options, 'storage_get', '{ key, ...opts }') + ',',
    '    list: (opts) => ' + runtimeOrbitCall(options, 'storage_list', 'opts ?? {}') + ',',
    '    delete: (key) => ' + runtimeOrbitCall(options, 'storage_delete', '{ key }') + ',',
    '    url: (key) => ' + runtimeOrbitCall(options, 'storage_url', '{ key }') + ',',
    '    read: (key, opts) => ' +
      runtimeOrbitCall(options, 'storage_read', '{ key, ...opts }') +
      ',',
    '  },',
    '  cache: {',
    '    get: (key) => ' + runtimeOrbitCall(options, 'cache_get', '{ key }') + ',',
    '    set: (key, value, ttl_seconds) => ' +
      runtimeOrbitCall(options, 'cache_set', '{ key, value, ttl_seconds }') +
      ',',
    '    delete: (key) => ' + runtimeOrbitCall(options, 'cache_delete', '{ key }') + ',',
    '  },',
    '  socket: {',
    '    url: (channel, opts) => ' +
      runtimeOrbitCall(options, 'socket_url', '{ channel, ...opts }') +
      ',',
    '    broadcast: (channel, event, opts) => ' +
      runtimeOrbitCall(options, 'socket_broadcast', '{ channel, event, ...opts }') +
      ',',
    '    stats: (channel) => ' + runtimeOrbitCall(options, 'socket_stats', '{ channel }') + ',',
    '  },',
    '  db: ' + dbExpression + ',',
    '  tools: {',
    '    search: (query, opts) => ' +
      runtimeOrbitCall(options, 'tools_search', '__hrbr_tools_search_args(query, opts)') +
      ',',
    '    describe: (tool_id) => ' +
      runtimeOrbitCall(options, 'tools_describe', '{ tool_id }') +
      ',',
    '    namespaces: () => ' + runtimeOrbitCall(options, 'tools_namespaces', '{}') + ',',
    '  },',
    '  artifact: {',
    '    read: (refOrId) => ' + runtimeOrbitCall(options, 'artifact_read', 'refOrId') + ',',
    '  },',
    '  ai: {',
    '    run: (model, input, opts) => typeof model === "string" ? ' +
      runtimeOrbitCall(options, 'ai_run', '{ model, input, ...opts }') +
      ' : ' +
      runtimeOrbitCall(options, 'ai_run', '{ input: model, ...input }') +
      ',',
    '    generate: (input, opts) => ' +
      runtimeOrbitCall(options, 'ai_generate', '{ input, opts }') +
      ',',
    '    summarize: (input, opts) => ' +
      runtimeOrbitCall(options, 'ai_summarize', '{ input, opts }') +
      ',',
    '    embed: (input, opts) => ' + runtimeOrbitCall(options, 'ai_embed', '{ input, opts }') + ',',
    '    classify: (input, opts) => ' +
      runtimeOrbitCall(options, 'ai_classify', '{ input, opts }') +
      ',',
    '    rerank: (input, opts) => ' +
      runtimeOrbitCall(options, 'ai_rerank', '{ input, opts }') +
      ',',
    '    models: (opts) => ' + runtimeOrbitCall(options, 'ai_models', 'opts ?? {}') + ',',
    '  },',
    '};',
  ]
  if (exposeOrbit) {
    lines.push('const ' + orbit + ' = ' + workspace + ';')
  }
  if (options.exposeHrbr) {
    lines.push(
      'const __hrbr_jobs = ' +
        (options.jobsExpression ?? defaultRuntimeOrbitJobsExpression()) +
        ';',
      'const ' + hrbr + ' = Object.freeze({',
      '  storage: ' + workspace + '.storage,',
      '  cache: ' + workspace + '.cache,',
      '  db: ' + workspace + '.db,',
      '  ai: ' + workspace + '.ai,',
      '  tools: ' + workspace + '.tools,',
      '  artifact: ' + workspace + '.artifact,',
      '  jobs: __hrbr_jobs,',
      '});'
    )
    if (exposeGlobalHrbr) {
      lines.push('globalThis.' + hrbr + ' = ' + hrbr + ';')
    }
  }
  return lines.join('\n')
}
export function createRuntimeOrbitPreamble(options: { readonly hrbr?: boolean } = {}): string {
  return createRuntimeOrbitSurfaceSource({ exposeHrbr: options.hrbr })
}
function preparedRuntimeOrbitProvider(
  key = RUNTIME_ORBIT_DEFAULT_CAPABILITY_KEY,
  metadata?: RuntimeMetadata | undefined
): RuntimeOrbitPreparedProvider {
  return {
    kind: 'orbit',
    key,
    ...(metadata ? { metadata } : {}),
  }
}

function runtimeOrbitProviderMetadata(metadata?: RuntimeMetadata | undefined): RuntimeMetadata {
  return {
    ...(metadata ?? {}),
    primitiveCount: RUNTIME_ORBIT_PRIMITIVES.length,
  }
}

export const RuntimeOrbitProviderLive = Layer.succeed(RuntimeOrbitProvider, {
  prepare: (input) =>
    Effect.succeed(
      preparedRuntimeOrbitProvider(input?.key, runtimeOrbitProviderMetadata(input?.metadata))
    ),
})

export const RuntimeOrbitCapabilityProvider: RuntimeCapabilityProvider = {
  kind: 'orbit',
  prepare: (input) =>
    Effect.succeed(
      preparedRuntimeOrbitProvider(input.key, runtimeOrbitProviderMetadata(input.metadata))
    ),
}
